import sympy

def build_instance(rng):
    coefficient = rng.randint(1, 10)
    constant = rng.randint(-10, 10)
    target = rng.randint(-20, 20)
    bound = rng.randint(1, 100)
    x = sympy.symbols('x')
    equation = coefficient * x + constant - target
    solutions = sympy.solve(equation, x)
    valid_solutions = [sol for sol in solutions if sol.is_integer and 0 <= sol <= bound]
    answer = len(valid_solutions)
    check = len([sol for sol in solutions if sol.is_integer and 0 <= sol <= bound])
    parameters = {'coefficient': coefficient, 'constant': constant, 'target': target, 'bound': bound}
    return (parameters, answer, check)



