import sympy

def build_instance(rng):
    first_term = rng.randint(1, 10)
    common_difference = rng.randint(1, 5)
    term_count = rng.randint(3, 10)
    terms = [first_term + i * common_difference for i in range(term_count)]
    answer = sympy.prod(terms)
    check = 1
    for term in terms:
        check *= term
    parameters = {'first_term': first_term, 'common_difference': common_difference, 'term_count': term_count}
    return (parameters, answer, check)



